# Let's analyze the input/output pairs manually first
inputs = ['bheba', 'iuw', 'axhbf', 'hikxwi', 'ijh']
outputs = ['bheba', 'iuw', 'avehbg', 'hikvewi', 'idygxh']

print("Input strings:")
for i, inp in enumerate(inputs):
    print(f"  {i}: '{inp}'")

print("\nOutput strings:")
for i, outp in enumerate(outputs):
    print(f"  {i}: '{outp}'")

print("\nDifferences:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        print(f"  {i}: '{inp}' -> '{outp}'")

